'use client';

// Tabs for the toolkit's strategy families and the Patterns period toggle.
// Generated by the shadcn/ui CLI on Radix Tabs (arrow keys move between
// tabs, the panel is linked for screen readers) and adapted: 48px pill tabs
// that wrap on a narrow phone, with the selected tab filled, not just tinted.
import * as React from 'react';
import { cn } from '@/lib/utils';
import { Tabs as TabsPrimitive } from 'radix-ui';

function Tabs({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Root>) {
  return <TabsPrimitive.Root data-slot="tabs" className={cn('flex flex-col gap-4', className)} {...props} />;
}

function TabsList({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.List>) {
  return <TabsPrimitive.List data-slot="tabs-list" className={cn('flex flex-wrap gap-2', className)} {...props} />;
}

function TabsTrigger({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Trigger>) {
  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      className={cn(
        'inline-flex min-h-12 items-center gap-2 rounded-full border border-line bg-surface px-4 text-body text-ink disabled:opacity-50 data-active:border-primary data-active:bg-primary data-active:font-bold data-active:text-on-primary [&_svg]:size-5 [&_svg]:shrink-0',
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return <TabsPrimitive.Content data-slot="tabs-content" className={cn('flex-1', className)} {...props} />;
}

export { Tabs, TabsList, TabsTrigger, TabsContent };
